/// TOML subset parser.
///
/// Supports:
/// - comments (#)
/// - blank lines and leading/trailing whitespace
/// - bare keys and dotted keys
/// - tables ([owner]) and nested tables ([database.settings])
/// - strings with \\\", \\\\, \\n, \\t escapes
/// - integers, booleans, arrays of those values
/// - duplicate-key errors with useful message

///|
suberror ParseError {
  DuplicateKey(String, Int)
  InvalidSyntax(String, Int)
  UnterminatedString(Int)
  InvalidEscape(String, Int)
  ExpectedKey(Int)
  ExpectedValue(Int)
  ExpectedEquals(Int)
  UnexpectedChar(Char, Int)
  NestedArrayNotSupported(Int)
  MixedArrayTypes(Int)
} derive(Debug)

///|
/// Parse TOML text into a Json value.
pub fn parse_toml(text : String) -> Json raise ParseError {
  let lines = split_lines(text)
  let mut assignments : Array[(Array[String], Json)] = []
  let mut current_table : Array[String] = []
  let mut line_no = 0

  while line_no < lines.length() {
    let raw = lines[line_no].trim()
    line_no = line_no + 1
    if raw == "" || raw.starts_with("#") {
      continue
    }
    if raw.starts_with("[") {
      // table header
      if !raw.ends_with("]") {
        raise ParseError::InvalidSyntax("malformed table header", line_no)
      }
      let inner = raw[1 : raw.length() - 1].trim()
      if inner == "" {
        raise ParseError::InvalidSyntax("empty table name", line_no)
      }
      current_table = split_dotted_key(inner, line_no)
      continue
    }
    // key = value
    let eq_pos = raw.find_first("=").or(raise ParseError::ExpectedEquals(line_no))
    let key_raw = raw[0 : eq_pos].trim()
    let val_raw = raw[eq_pos + 1 :].trim()
    if key_raw == "" {
      raise ParseError::ExpectedKey(line_no)
    }
    if val_raw == "" {
      raise ParseError::ExpectedValue(line_no)
    }
    let keys = split_dotted_key(key_raw, line_no)
    let val = parse_value(val_raw, line_no)

    // Build full path
    let mut full_path = Array::new()
    for k in current_table {
      full_path.push(k)
    }
    for k in keys {
      full_path.push(k)
    }
    assignments.push((full_path, val))
  }

  // Build JSON tree from assignments
  let mut root : Map[String, Json] = Map::new()
  for (path, val) in assignments {
    insert_into_map(&mut root, path, 0, val, 0)
  }
  Json::Object(root)
}

///|
fn split_lines(text : String) -> Array[String] {
  let mut lines = Array::new()
  let mut start = 0
  for i = 0; i < text.length(); i = i + 1 {
    if text[i] == '\n' {
      lines.push(text[start : i].to_owned())
      start = i + 1
    }
  }
  if start < text.length() {
    lines.push(text[start :].to_owned())
  }
  lines
}

///|
fn split_dotted_key(raw : String, line_no : Int) -> Array[String] raise ParseError {
  let mut keys = Array::new()
  let mut i = 0
  let len = raw.length()
  while i < len {
    let c = raw[i]
    if c == ' ' || c == '\t' {
      i = i + 1
      continue
    }
    if c == '"' {
      let (quoted, end) = parse_basic_string(raw, i, line_no)
      keys.push(quoted)
      i = end
    } else if c == '\'' {
      let mut j = i + 1
      while j < len {
        if raw[j] == '\'' {
          break
        }
        j = j + 1
      }
      if j >= len {
        raise ParseError::UnterminatedString(line_no)
      }
      keys.push(raw[i + 1 : j].to_owned())
      i = j + 1
    } else {
      // bare key: letters, digits, underscores, hyphens
      let mut j = i
      while j < len {
        let ch = raw[j]
        if ch == '.' || ch == ' ' || ch == '\t' {
          break
        }
        j = j + 1
      }
      if j > i {
        keys.push(raw[i : j].to_owned())
      }
      i = j
    }
    // skip whitespace and dots
    while i < len && (raw[i] == ' ' || raw[i] == '\t' || raw[i] == '.') {
      i = i + 1
    }
  }
  keys
}

///|
fn parse_basic_string(raw : String, start : Int, line_no : Int) -> (String, Int) raise ParseError {
  let mut i = start
  let len = raw.length()
  if i >= len || raw[i] != '"' {
    raise ParseError::UnterminatedString(line_no)
  }
  i = i + 1
  let mut buf = String::new()
  while i < len {
    let c = raw[i]
    if c == '"' {
      i = i + 1
      return (buf, i)
    }
    if c == '\\' {
      i = i + 1
      if i >= len {
        raise ParseError::UnterminatedString(line_no)
      }
      match raw[i] {
        '"' => { buf = buf + "\""; i = i + 1 }
        '\\' => { buf = buf + "\\"; i = i + 1 }
        'n' => { buf = buf + "\n"; i = i + 1 }
        't' => { buf = buf + "\t"; i = i + 1 }
        'r' => { buf = buf + "\r"; i = i + 1 }
        _ => raise ParseError::InvalidEscape("unknown escape \\" + raw[i].to_string(), line_no)
      }
      continue
    }
    buf = buf + c.to_string()
    i = i + 1
  }
  raise ParseError::UnterminatedString(line_no)
}

///|
fn parse_value(raw : String, line_no : Int) -> Json raise ParseError {
  let s = raw.trim()
  if s == "" {
    raise ParseError::ExpectedValue(line_no)
  }
  let first = s[0]
  match first {
    '"' => {
      let (str, _) = parse_basic_string(s, 0, line_no)
      Json::string(str)
    }
    't' => {
      if s == "true" {
        Json::boolean(true)
      } else {
        raise ParseError::InvalidSyntax("invalid value: " + s, line_no)
      }
    }
    'f' => {
      if s == "false" {
        Json::boolean(false)
      } else {
        raise ParseError::InvalidSyntax("invalid value: " + s, line_no)
      }
    }
    '[' => {
      parse_array(s, line_no)
    }
    _ => {
      // integer (possibly negative)
      if s.starts_with("-") || is_digit(first) {
        let n : Int = @string.from_str(s) catch {
          _ => raise ParseError::InvalidSyntax("invalid integer: " + s, line_no)
        }
        Json::number(n.to_double(), repr=s.to_owned())
      } else {
        raise ParseError::UnexpectedChar(first, line_no)
      }
    }
  }
}

///|
fn is_digit(c : Char) -> Bool {
  c >= '0' && c <= '9'
}

///|
fn parse_array(raw : String, line_no : Int) -> Json raise ParseError {
  let s = raw.trim()
  if !s.starts_with("[") || !s.ends_with("]") {
    raise ParseError::InvalidSyntax("malformed array", line_no)
  }
  let inner = s[1 : s.length() - 1].trim()
  if inner == "" {
    return Json::array([])
  }
  let elements = split_array_elements(inner, line_no)
  let mut arr = Array::new()
  let mut first_type : String? = None
  for elem in elements {
    let val = parse_value(elem, line_no)
    let typ = json_type_name(val)
    match first_type {
      None => first_type = Some(typ)
      Some(t) if t != typ => raise ParseError::MixedArrayTypes(line_no)
      _ => ()
    }
    arr.push(val)
  }
  Json::array(arr)
}

///|
fn json_type_name(v : Json) -> String {
  match v {
    Json::String(_) => "string"
    Json::Number(_, _) => "integer"
    Json::Boolean(_) => "boolean"
    _ => "unknown"
  }
}

///|
fn split_array_elements(raw : String, line_no : Int) -> Array[String] raise ParseError {
  let mut elems = Array::new()
  let mut depth = 0
  let mut start = 0
  let mut in_string = false
  let len = raw.length()
  for i = 0; i < len; i = i + 1 {
    let c = raw[i]
    if c == '"' && (i == 0 || raw[i - 1] != '\\') {
      in_string = not(in_string)
    }
    if not(in_string) {
      if c == '[' {
        depth = depth + 1
      } else if c == ']' {
        depth = depth - 1
      } else if c == ',' && depth == 0 {
        let elem = raw[start : i].trim().to_owned()
        if elem != "" {
          elems.push(elem)
        }
        start = i + 1
      }
    }
  }
  let last = raw[start :].trim().to_owned()
  if last != "" {
    elems.push(last)
  }
  elems
}

///|
/// Insert a value at a dotted path into a map, creating intermediate objects.
/// Reports duplicate key errors.
fn insert_into_map(
  map : &mut Map[String, Json],
  path : Array[String],
  idx : Int,
  value : Json,
  line_no : Int
) -> Unit raise ParseError {
  if idx >= path.length() {
    return
  }
  let key = path[idx]
  if idx == path.length() - 1 {
    // leaf: set value
    if map.contains(key) {
      raise ParseError::DuplicateKey(key, line_no)
    }
    map.set(key, value)
  } else {
    // intermediate: ensure object exists and recurse
    match map.get(key) {
      None => {
        let new_obj : Map[String, Json] = Map::new()
        map.set(key, Json::Object(new_obj))
      }
      Some(Json::Object(_)) => ()
      Some(_) => raise ParseError::InvalidSyntax(
        "key \"" + key + "\" already exists as a non-table value", line_no,
      )
    }
    // Recurse into the nested object
    match map[key] {
      Json::Object(m) => {
        // MoonBit: can't get &mut to inner map. Use workaround:
        // clone, modify, set back
        let mut inner = Map::new()
        for (k, v) in m {
          inner.set(k, v)
        }
        insert_into_map(&mut inner, path, idx + 1, value, line_no)
        map.set(key, Json::Object(inner))
      }
      _ => unreachable!()
    }
  }
}
