/// TOML subset parser.
///
/// Supports:
/// - comments (#)
/// - blank lines and leading/trailing whitespace
/// - bare keys and dotted keys
/// - tables ([owner]) and nested tables ([database.settings])
/// - strings with \\\", \\\\, \\n, \\t escapes
/// - integers, booleans, arrays of those values
/// - duplicate-key errors with useful message

///|
suberror ParseError {
  DuplicateKey(String, Int)
  InvalidSyntax(String, Int)
  UnterminatedString(Int)
  InvalidEscape(String, Int)
  ExpectedKey(Int)
  ExpectedValue(Int)
  ExpectedEquals(Int)
  UnexpectedChar(Char, Int)
  MixedArrayTypes(Int)
} derive(Debug)

///|
/// Parse TOML text into a Json value.
pub fn parse_toml(text : String) -> Json raise ParseError {
  let mut assignments : Array[(Array[String], Json, Int)] = []
  let mut current_table : Array[String] = []
  let mut line_no = 0
  let lines = split_lines(text)

  while line_no < lines.length() {
    let raw = lines[line_no].trim()
    line_no = line_no + 1
    if raw.is_empty() || raw[0] == 35 {
      continue
    }
    if raw[0] == 91 {
      // table header: [name] or [a.b.c]
      if not(raw.has_suffix("]")) {
        raise ParseError::InvalidSyntax("malformed table header", line_no)
      }
      let inner = raw.sub(start=1, end=raw.length() - 1).trim()
      if inner.is_empty() {
        raise ParseError::InvalidSyntax("empty table name", line_no)
      }
      current_table = split_dotted_key(inner, line_no)
      continue
    }
    // key = value
    match raw.find("=") {
      None => raise ParseError::ExpectedEquals(line_no)
      Some(eq_pos) => {
        let key_raw = raw.sub(start=0, end=eq_pos).trim()
        let val_raw = raw.sub(start=eq_pos + 1, end=raw.length()).trim()
        if key_raw.is_empty() {
          raise ParseError::ExpectedKey(line_no)
        }
        if val_raw.is_empty() {
          raise ParseError::ExpectedValue(line_no)
        }
        let keys = split_dotted_key(key_raw, line_no)
        let val = parse_value(val_raw, line_no)

        let full_path = Array::new()
        for k in current_table {
          full_path.push(k)
        }
        for k in keys {
          full_path.push(k)
        }
        assignments.push((full_path, val, line_no))
      }
    }
  }

  // Build JSON tree functionally
  build_tree(assignments)
}

///|
fn split_lines(text : String) -> Array[StringView] {
  let lines = Array::new()
  let mut start = 0
  let len = text.length()
  for i = 0; i < len; i = i + 1 {
    if text[i] == 10 {
      lines.push(text.sub(start=start, end=i))
      start = i + 1
    }
  }
  if start < len {
    lines.push(text.sub(start=start, end=len))
  }
  lines
}

///|
fn split_dotted_key(raw : StringView, line_no : Int) -> Array[String] raise ParseError {
  let keys = Array::new()
  let mut i = 0
  let len = raw.length()
  while i < len {
    let c = raw[i]
    if c == 32 || c == 9 {
      i = i + 1
      continue
    }
    if c == 34 {
      let (quoted, end) = parse_basic_string(raw, i, line_no)
      keys.push(quoted)
      i = end
    } else if c == 39 {
      let mut j = i + 1
      while j < len {
        if raw[j] == 39 {
          break
        }
        j = j + 1
      }
      if j >= len {
        raise ParseError::UnterminatedString(line_no)
      }
      keys.push(raw.sub(start=i + 1, end=j).to_owned())
      i = j + 1
    } else {
      // bare key
      let mut j = i
      while j < len {
        let ch = raw[j]
        if ch == 46 || ch == 32 || ch == 9 {
          break
        }
        j = j + 1
      }
      if j > i {
        keys.push(raw.sub(start=i, end=j).to_owned())
      }
      i = j
    }
    // skip whitespace and dots
    while i < len {
      let ch = raw[i]
      if ch == 32 || ch == 9 || ch == 46 {
        i = i + 1
      } else {
        break
      }
    }
  }
  keys
}

///|
fn parse_basic_string(raw : StringView, start : Int, line_no : Int) -> (String, Int) raise ParseError {
  let len = raw.length()
  let mut i = start
  if i >= len || raw[i] != 34 {
    raise ParseError::UnterminatedString(line_no)
  }
  i = i + 1
  let mut buf = String::new()
  while i < len {
    let c = raw[i]
    if c == 34 {
      i = i + 1
      return (buf, i)
    }
    if c == 92 {
      i = i + 1
      if i >= len {
        raise ParseError::UnterminatedString(line_no)
      }
      match raw[i] {
        34 => { buf = buf + "\""; i = i + 1 }  // \"
        92 => { buf = buf + "\\"; i = i + 1 }  // \\
        110 => { buf = buf + "\n"; i = i + 1 } // \n
        116 => { buf = buf + "\t"; i = i + 1 } // \t
        114 => { buf = buf + "\r"; i = i + 1 } // \r
        _ => raise ParseError::InvalidEscape(
          "unknown escape \\" + Char::from_code(raw[i].to_int()).to_string(), line_no,
        )
      }
      continue
    }
    buf = buf + Char::from_code(c.to_int()).to_string()
    i = i + 1
  }
  raise ParseError::UnterminatedString(line_no)
}

///|
fn parse_value(raw : StringView, line_no : Int) -> Json raise ParseError {
  if raw.is_empty() {
    raise ParseError::ExpectedValue(line_no)
  }
  let first = raw[0]
  if first == 34 {
    let (str, _) = parse_basic_string(raw, 0, line_no)
    return Json::string(str)
  }
  if raw.equal_to_string("true") {
    return Json::boolean(true)
  }
  if raw.equal_to_string("false") {
    return Json::boolean(false)
  }
  if first == 91 {
    return parse_array(raw, line_no)
  }
  if first == 45 || (first >= 48 && first <= 57) {
    let s = raw.to_owned()
    let n : Int = @string.from_str(s) catch {
      _ => raise ParseError::InvalidSyntax("invalid integer: " + s, line_no)
    }
    return Json::number(n.to_double(), repr=s)
  }
  let ch = Char::from_code(first.to_int())
  raise ParseError::UnexpectedChar(ch, line_no)
}

///|
fn parse_array(raw : StringView, line_no : Int) -> Json raise ParseError {
  if not(raw.has_prefix("[")) || not(raw.has_suffix("]")) {
    raise ParseError::InvalidSyntax("malformed array", line_no)
  }
  let inner = raw.sub(start=1, end=raw.length() - 1).trim()
  if inner.is_empty() {
    return Json::array([])
  }
  let elements = split_array_elements(inner, line_no)
  let arr = Array::new()
  let mut first_type : String? = None
  for elem in elements {
    let val = parse_value(elem, line_no)
    let typ = json_type_name(val)
    match first_type {
      None => first_type = Some(typ)
      Some(t) => {
        if t != typ {
          raise ParseError::MixedArrayTypes(line_no)
        }
      }
    }
    arr.push(val)
  }
  Json::array(arr)
}

///|
fn json_type_name(v : Json) -> String {
  match v {
    Json::String(_) => "string"
    Json::Number(_, _) => "integer"
    Json::Boolean(_) => "boolean"
    _ => "unknown"
  }
}

///|
fn split_array_elements(raw : StringView, line_no : Int) -> Array[StringView] raise ParseError {
  let elems = Array::new()
  let mut depth = 0
  let mut start = 0
  let mut in_string = false
  let len = raw.length()
  for i = 0; i < len; i = i + 1 {
    let c = raw[i]
    if c == 34 && (i == 0 || raw[i - 1] != 92) {
      in_string = not(in_string)
    }
    if not(in_string) {
      if c == 91 {
        depth = depth + 1
      } else if c == 93 {
        depth = depth - 1
      } else if c == 44 && depth == 0 {
        let elem = raw.sub(start=start, end=i).trim()
        if not(elem.is_empty()) {
          elems.push(elem)
        }
        start = i + 1
      }
    }
  }
  let last = raw.sub(start=start, end=len).trim()
  if not(last.is_empty()) {
    elems.push(last)
  }
  elems
}

///|
/// Build a JSON tree from flat (path, value, line_no) assignments.
fn build_tree(assignments : Array[(Array[String], Json, Int)]) -> Json raise ParseError {
  let mut root : Map[String, Json] = Map([], capacity=10)
  for item in assignments {
    root = insert_into_map(root, item.0, 0, item.1, item.2)
  }
  Json::Object(root)
}

///|
/// Functionally insert a value at a path into an immutable map.
fn insert_into_map(
  map : Map[String, Json],
  path : Array[String],
  idx : Int,
  value : Json,
  line_no : Int
) -> Map[String, Json] raise ParseError {
  if idx >= path.length() {
    return map
  }
  let key = path[idx]
  if idx == path.length() - 1 {
    // leaf: check for duplicate, then insert
    if map.contains(key) {
      raise ParseError::DuplicateKey(key, line_no)
    }
    let mut new_map = copy_map(map)
    new_map.set(key, value)
    return new_map
  } else {
    // intermediate: recurse into nested object
    let child : Map[String, Json] = match map.get(key) {
      None => Map([], capacity=4)
      Some(Json::Object(m)) => copy_map(m)
      Some(_) => raise ParseError::InvalidSyntax(
        "key \"" + key + "\" already exists as a non-table value", line_no,
      )
    }
    let new_child = insert_into_map(child, path, idx + 1, value, line_no)
    let mut new_map = copy_map(map)
    new_map.set(key, Json::Object(new_child))
    return new_map
  }
}

/// Copy all entries from one map to a new map
fn copy_map(m : Map[String, Json]) -> Map[String, Json] {
  let mut result : Map[String, Json] = Map([], capacity=m.size())
  m.each(fn(k, v) {
    result.set(k, v)
  })
  result
}
