{"content": "///|
/// TOML to JSON CLI converter.
///
/// Reads TOML from a file or stdin and prints JSON to stdout.

///|
struct Config {
  input : String
  stdin : Bool
}

///|
async fn main {
  let config = @argparse.parse(
      Command(
        "tomljson",
        about="Convert TOML to JSON. Reads from a file or stdin.",
        flags=[
          FlagArg("stdin", long="stdin", about="Read TOML from stdin instead of a file."),
        ],
        positionals=[
          PositionArg("input", default_values=["-"], about="Input TOML file path."),
        ],
      ),
    )
    |> config_from_matches
  let input = if config.stdin {
    @stdio.stdin.read_all().text()
  } else {
    @fs.read_file(config.input).text()
  }
  let toml_text = input
  let json = @eval/tomljson.parse_toml(toml_text) catch {
    err => {
      @stdio.stderr.write_string("Error: " + @debug.to_string(err) + "\n")
      return
    }
  }
  @stdio.stdout.write_string(json.stringify() + "\n")
}

///|
fn config_from_matches(matches : @argparse.Matches) -> Config raise {
  match matches {
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : Some(stdin), .. },
      ..,
    } => { input, stdin }
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : None, .. },
      ..,
    } => {
      let stdin = false
      { input, stdin }
    }
    _ => fail("missing parsed argument: input")
  }
}
